from django.db import migrations, models


def juntar_nome_na_descricao(apps, schema_editor):
    """O antigo 'nome' passa a ser a descrição. Se já havia descrição, ela fica embaixo."""
    Atividade = apps.get_model("sge", "Atividade")
    for a in Atividade.objects.all():
        nome = (a.nome or "").strip()
        antiga = (a.descricao or "").strip()
        a.descricao = f"{nome}\n\n{antiga}" if nome and antiga and antiga != nome else (nome or antiga)
        a.save(update_fields=["descricao"])


def separar_descricao_em_nome(apps, schema_editor):
    """Volta atrás: a 1ª linha da descrição vira o nome."""
    Atividade = apps.get_model("sge", "Atividade")
    for a in Atividade.objects.all():
        partes = (a.descricao or "").split("\n\n", 1)
        a.nome = partes[0][:200]
        a.descricao = partes[1] if len(partes) > 1 else ""
        a.save(update_fields=["nome", "descricao"])


